import re, os, sys
def resolves(base_dir, spec):
    if spec.startswith('@/'): spec='resources/js/'+spec[2:]
    else: spec=os.path.normpath(os.path.join(base_dir, spec))
    for c in [spec, spec+'.vue', spec+'.ts', spec+'.tsx', spec+'.js', spec+'/index.ts', spec+'/index.vue']:
        if os.path.exists(c): return c
    return None
# BFS from MainPage.vue following value imports (skip type-only best effort: track all, mark)
start='resources/js/pages/MainPage.vue'
seen=set()
missing=[]
queue=[start]
while queue:
    p=queue.pop()
    if p in seen: continue
    seen.add(p)
    if not os.path.exists(p):
        missing.append(p); continue
    d=os.path.dirname(p)
    src=open(p,encoding='utf-8').read()
    # strip <script> lang="ts" type-only imports are `import type` or `import { type X }`
    for m in re.finditer(r'''(?<!type )import\s+(type\s+)?[^'"]*?from\s+['"]([^'"]+)['"]''', src):
        typemarker = m.group(1)
        spec=m.group(2)
        if spec.startswith(('@','.')):
            r=resolves(d, spec)
            if r is None:
                missing.append(f"{p} -> {spec} (type-import={bool(typemarker)})")
            elif r not in seen and r.endswith(('.vue','.ts','.tsx','.js')):
                queue.append(r)
print("MainPage.vue reachable files:")
for s in sorted(seen): print("  ", s)
print("MISSING in MainPage chain:")
for m in missing: print("  ", m)
if not missing: print("   (none)")
EOF

